from __future__ import annotations
"""
沙箱会话管理器
"""
import threading
import time
import os
import uuid
from typing import Dict, Optional, List, Any
from .persistent_sandbox import PersistentEnvironmentSandbox


class SandboxSessionManager:
    def __init__(self):
        self._sessions: Dict[str, PersistentEnvironmentSandbox] = {}
        self._lock = threading.RLock()
        self._cleanup_thread = None
        self._running = True

        self._process_id = os.getpid()
        self._process_uuid = str(uuid.uuid4())[:8]

        self._start_cleanup_thread()

    def _start_cleanup_thread(self):
        """启动清理线程"""
        def cleanup_loop():
            while self._running:
                try:
                    self._cleanup_expired_sessions()
                    time.sleep(300)
                except Exception as e:
                    print(f"[SESSION_MANAGER] Process {self._process_id} cleanup thread error: {e}")

        self._cleanup_thread = threading.Thread(target=cleanup_loop, daemon=True)
        self._cleanup_thread.start()

    def _cleanup_expired_sessions(self):
        """清理过期的会话 - 只清理本进程创建的session"""
        with self._lock:
            expired_sessions = []
            for session_id, session in self._sessions.items():
                if (session_id.startswith(f"p{self._process_id}_") and 
                    session.is_timeout()):
                    expired_sessions.append(session_id)

            for session_id in expired_sessions:
                print(f"[SESSION_MANAGER] Process {self._process_id} cleaning up expired session: {session_id}")
                session = self._sessions.pop(session_id, None)
                if session:
                    try:
                        session.cleanup_session()
                    except Exception as e:
                        print(f"[SESSION_MANAGER] Error cleaning up session {session_id}: {e}")

    def create_session(
        self,
        session_id: Optional[str] = None,
        memory_limit_mb: int = 512,
        timeout_minutes: int = 30,
        debug: bool = False,
        **kwargs
    ) -> PersistentEnvironmentSandbox:
        """创建新的持久化会话"""
        with self._lock:
            if session_id is None:
                unique_id = str(uuid.uuid4())[:8]
                session_id = f"p{self._process_id}_{self._process_uuid}_{unique_id}"
            else:
                session_id = f"p{self._process_id}_{self._process_uuid}_{session_id}"

            session = PersistentEnvironmentSandbox(
                memory_limit_mb=memory_limit_mb,
                timeout_minutes=timeout_minutes,
                debug=debug,
                session_id=session_id,
                **kwargs
            )

            self._sessions[session.session_id] = session
            print(f"[SESSION_MANAGER] Process {self._process_id} created session: {session_id}")
            return session

    def get_session(self, session_id: str) -> Optional[PersistentEnvironmentSandbox]:
        """获取会话"""
        with self._lock:
            session = self._sessions.get(session_id)
            if session and not session.is_timeout():
                session.touch()
                return session
            elif session:
                # 只有确实超时才清理
                if session.is_timeout():
                    self._sessions.pop(session_id, None)
                    try:
                        session.cleanup_session()
                    except Exception as e:
                        print(f"[SESSION_MANAGER] Error cleaning up expired session {session_id}: {e}")
            return None

    def remove_session(self, session_id: str) -> bool:
        """移除会话"""
        with self._lock:
            session = self._sessions.pop(session_id, None)
            if session:
                try:
                    session.cleanup_session()
                    print(f"[SESSION_MANAGER] Process {self._process_id} removed session: {session_id}")
                    return True
                except Exception as e:
                    print(f"[SESSION_MANAGER] Error removing session {session_id}: {e}")
            return False

    def list_sessions(self) -> List[Dict[str, Any]]:
        """列出所有活跃会话"""
        with self._lock:
            sessions = []
            for session_id, session in self._sessions.items():
                try:
                    if not session.is_timeout():
                        sessions.append({
                            'session_id': session_id,
                            'created_at': session.created_at,
                            'last_accessed': session.last_accessed,
                            'timeout_minutes': session.timeout_minutes,
                            'time_remaining': session.get_remaining_time(),
                            'memory_limit_mb': session.memory_limit_mb,
                            'process_id': self._process_id,
                        })
                    else:
                        sessions.append({
                            'session_id': session_id,
                            'status': 'expired',
                            'time_remaining': 0,
                            'process_id': self._process_id,
                        })
                except Exception as e:
                    print(f"[SESSION_MANAGER] Error getting session info for {session_id}: {e}")
            return sessions

    def cleanup_all_sessions(self):
        """清理所有会话"""
        with self._lock:
            session_ids = list(self._sessions.keys())
            for session_id in session_ids:
                session = self._sessions.pop(session_id, None)
                if session:
                    try:
                        session.cleanup_session()
                        print(f"[SESSION_MANAGER] Process {self._process_id} cleaned up session: {session_id}")
                    except Exception as e:
                        print(f"[SESSION_MANAGER] Error cleaning up session {session_id}: {e}")
            self._sessions.clear()

    def get_session_stats(self) -> Dict[str, Any]:
        """获取会话统计信息"""
        with self._lock:
            total_sessions = len(self._sessions)
            active_sessions = 0
            expired_sessions = 0

            for session in self._sessions.values():
                try:
                    if session.is_timeout():
                        expired_sessions += 1
                    else:
                        active_sessions += 1
                except Exception:
                    expired_sessions += 1

            return {
                'total_sessions': total_sessions,
                'active_sessions': active_sessions,
                'expired_sessions': expired_sessions,
                'session_ids': list(self._sessions.keys()),
                'process_id': self._process_id,
            }

    def extend_session_timeout(self, session_id: str, additional_minutes: int = 5) -> bool:
        """延长会话超时时间"""
        with self._lock:
            session = self._sessions.get(session_id)
            if session and not session.is_timeout():
                try:
                    session.extend_timeout(additional_minutes)
                    print(f"[SESSION_MANAGER] Process {self._process_id} extended timeout for session: {session_id}")
                    return True
                except Exception as e:
                    print(f"[SESSION_MANAGER] Error extending timeout for session {session_id}: {e}")
            return False

    def shutdown(self):
        """关闭会话管理器"""
        print(f"[SESSION_MANAGER] Process {self._process_id} shutting down session manager")
        self._running = False
        if self._cleanup_thread and self._cleanup_thread.is_alive():
            self._cleanup_thread.join(timeout=2.0)
        self.cleanup_all_sessions()


_process_session_managers: Dict[int, SandboxSessionManager] = {}
_manager_lock = threading.Lock()


def get_global_session_manager() -> SandboxSessionManager:
    process_id = os.getpid()

    with _manager_lock:
        if process_id not in _process_session_managers:
            print(f"[SESSION_MANAGER] Creating new session manager for process {process_id}")
            _process_session_managers[process_id] = SandboxSessionManager()

        return _process_session_managers[process_id]


_global_session_manager = get_global_session_manager()

"""
Model adapter for unified tool calling interfaces across different models.
"""

from abc import ABC, abstractmethod
from typing import Any, Dict, List, Optional, Callable, Union
from enum import Enum

from .function_tool import FunctionTool


class ModelType(Enum):
    """Supported model types for tool calling."""
    OPENAI = "openai"
    TONGYI_DEEPRESEARCH = "tongyi_deepresearch"
    # Add more model types as needed


class BaseModelAdapter(ABC):
    """Base class for model-specific tool adapters."""

    @abstractmethod
    def adapt_tool_schema(self, func_tool: FunctionTool) -> FunctionTool:
        """Adapt a FunctionTool to the model-specific format."""
        pass

    @abstractmethod
    def adapt_function_call(self, func: Callable, args: Dict[str, Any]) -> Any:
        """Adapt function call arguments from model format to function format."""
        pass


class OpenAIAdapter(BaseModelAdapter):
    """Adapter for OpenAI-compatible models (default format)."""

    def adapt_tool_schema(self, func_tool: FunctionTool) -> FunctionTool:
        """OpenAI format is the default, no adaptation needed."""
        return func_tool

    def adapt_function_call(self, func: Callable, args: Dict[str, Any]) -> Any:
        """Direct call with original arguments."""
        return func(**args)


class TongyiDeepResearchAdapter(BaseModelAdapter):
    """Adapter for Tongyi DeepResearch model."""

    # Mapping from original function names to DeepResearch names
    FUNCTION_NAME_MAPPING = {
        "browser_search": "search",
        "browser_open": "Visit"
    }

    def adapt_tool_schema(self, func_tool: FunctionTool) -> FunctionTool:
        """Adapt tool schema for Tongyi DeepResearch format."""
        original_schema = func_tool.get_openai_tool_schema()
        func_name = original_schema["function"]["name"]

        # Create adapted schema based on function name
        if func_name == "browser_search":
            adapted_schema = {
                "type": "function",
                "function": {
                    "name": "search",
                    "description": "Search the web for information.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "query": {
                                "type": "array",
                                "items": {"type": "string"},
                                "description": "List of search queries."
                            }
                        },
                        "required": ["query"]
                    }
                }
            }
        elif func_name == "browser_open":
            adapted_schema = {
                "type": "function",
                "function": {
                    "name": "Visit",
                    "description": "Open a URL to visit a webpage.",
                    "parameters": {
                        "type": "object",
                        "properties": {
                            "url": {
                                "type": "array",
                                "items": {"type": "string"},
                                "description": "List of URLs to visit."
                            },
                            "goal": {
                                "type": "string",
                                "description": "Purpose of visiting the URL."
                            }
                        },
                        "required": ["url"]
                    }
                }
            }
        else:
            # For unknown functions, use original schema
            adapted_schema = original_schema

        # Create new FunctionTool with adapted schema
        return FunctionTool(
            func=func_tool.func,
            openai_tool_schema=adapted_schema
        )

    def adapt_function_call(self, func: Callable, args: Dict[str, Any]) -> Any:
        """Adapt function call arguments from DeepResearch format to original format."""
        func_name = func.__name__

        if func_name == "browser_search":
            # Convert array of queries to single query
            query_list = args.get("query", [])
            if isinstance(query_list, list) and query_list:
                # Use the first query or join multiple queries
                query = query_list[0] if len(query_list) == 1 else " ".join(query_list)
            else:
                query = str(query_list) if query_list else ""

            # Extract topn if provided, otherwise use default
            topn = args.get("topn", 10)
            return func(query=query, topn=topn)

        elif func_name == "browser_open":
            # Convert array of URLs to single URL
            url_list = args.get("url", [])
            if isinstance(url_list, list) and url_list:
                url = url_list[0]  # Use the first URL
            else:
                url = str(url_list) if url_list else ""

            # goal parameter is ignored as original function doesn't use it
            return func(url=url)

        else:
            # For unknown functions, use original arguments
            return func(**args)


class ModelAdapterFactory:
    """Factory for creating model-specific adapters."""

    _adapters = {
        ModelType.OPENAI: OpenAIAdapter,
        ModelType.TONGYI_DEEPRESEARCH: TongyiDeepResearchAdapter,
    }

    @classmethod
    def create_adapter(cls, model_type: Union[ModelType, str]) -> BaseModelAdapter:
        """Create an adapter for the specified model type."""
        if isinstance(model_type, str):
            try:
                model_type = ModelType(model_type.lower())
            except ValueError:
                raise ValueError(f"Unsupported model type: {model_type}")

        adapter_class = cls._adapters.get(model_type)
        if not adapter_class:
            raise ValueError(f"No adapter available for model type: {model_type}")

        return adapter_class()

    @classmethod
    def register_adapter(cls, model_type: ModelType, adapter_class: type):
        """Register a new adapter for a model type."""
        cls._adapters[model_type] = adapter_class

    @classmethod
    def get_supported_models(cls) -> List[ModelType]:
        """Get list of supported model types."""
        return list(cls._adapters.keys())


class AdaptiveToolWrapper:
    """Wrapper that adapts tools for different models."""

    def __init__(self, model_type: Union[ModelType, str] = ModelType.OPENAI):
        """Initialize with a specific model type."""
        self.adapter = ModelAdapterFactory.create_adapter(model_type)
        self.model_type = model_type

    def adapt_tools(self, tools: List[FunctionTool]) -> List[FunctionTool]:
        """Adapt a list of tools for the current model type."""
        return [self.adapter.adapt_tool_schema(tool) for tool in tools]

    def adapt_function_call(self, func: Callable, args: Dict[str, Any]) -> Any:
        """Adapt and execute a function call."""
        return self.adapter.adapt_function_call(func, args)

